      else begin                                                                     
        $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_lfsr_0.1/rtl/prim_lfsr.sv", 5,         
         "SboxByteAlign_A");                                                       
                                                        
