module prim_diff_decode #(
  // enables additional synchronization logic
  parameter bit AsyncOn = 1'b0,
  // Number of cycles a differential skew is tolerated before a signal integrity issue is flagged.
  // Only has an effect if AsyncOn = 1
  // 0 means no skew is tolerated (any mismatch is an immediate signal integrity error).
  // 1 means a one-cycle skew is tolerated.
  // Values larger than 1 are also supported.
  parameter int unsigned SkewCycles = 1
) (
  input        clk_i,
  input        rst_ni,
  // input diff pair
  input        diff_pi,
  input        diff_ni,
  // logical level and
  // detected edges
  output logic level_o,
  output logic rise_o,
  output logic fall_o,
  // either rise or fall
  output logic event_o,
  //signal integrity issue detected
  output logic sigint_o
);

  logic level_d, level_q;

  ///////////////////////////////////////////////////////////////
  // synchronization regs for incoming diff pair (if required) //
  ///////////////////////////////////////////////////////////////
  if (AsyncOn) begin : gen_async

    typedef enum logic [1:0] {IsStd, IsSkewing, SigInt} state_e;
    state_e state_d, state_q;
    logic diff_p_edge, diff_n_edge, diff_check_ok, level;

    // 2 sync regs, one reg for edge detection
    logic diff_pq, diff_nq, diff_pd, diff_nd;

    // Counter for skew cycles tolerated before flagging an issue
    // The width needs to accommodate SkewCycles + 1 to count up to SkewCycles.
    logic [prim_util_pkg::vbits(SkewCycles + 1)-1:0] skew_cnt_d, skew_cnt_q;

    prim_flop_2sync #(
      .Width(1),
      .ResetValue('0)
    ) i_sync_p (
      .clk_i,
      .rst_ni,
      .d_i(diff_pi),
      .q_o(diff_pd)
    );

    prim_flop_2sync #(
      .Width(1),
      .ResetValue(1'b1)
    ) i_sync_n (
      .clk_i,
      .rst_ni,
      .d_i(diff_ni),
      .q_o(diff_nd)
    );

    // detect level transitions
    assign diff_p_edge   = diff_pq ^ diff_pd;
    assign diff_n_edge   = diff_nq ^ diff_nd;

    // detect sigint issue
    assign diff_check_ok = diff_pd ^ diff_nd;

    // this is the current logical level
    assign level         = diff_pd;

    // outputs
    assign level_o  = level_d;
    assign event_o = rise_o | fall_o;

    // sigint detection is a bit more involved in async case since
    // we might have skew on the diff pair, which can result in a
    // N cycle sampling delay between the two wires
    // so we need a simple pattern matcher
    // the following waves are legal
    // clk    |   |   |   |   |   |   |   |
    //           _______     _______
    // p _______/        ...        \________
    //   _______                     ________
    // n        \_______ ... _______/
    //              ____     ___
    // p __________/     ...    \________
    //   _______                     ________
    // n        \_______ ... _______/
    //
    // i.e., level changes may be off by N cycle - which is permissible
    // as long as this condition is only N cycle long.


    always_comb begin : p_diff_fsm
      // default
      state_d    = state_q;
      level_d    = level_q;
      skew_cnt_d = skew_cnt_q;
      rise_o     = 1'b0;
      fall_o     = 1'b0;
      sigint_o   = 1'b0;

      unique case (state_q)
        // we remain here as long as
        // the diff pair is correctly encoded
        IsStd: begin
          if (diff_check_ok) begin
            level_d = level;
            if (diff_p_edge && diff_n_edge) begin
              if (level) begin
                rise_o = 1'b1;
              end else begin
                fall_o = 1'b1;
              end
            end
          end else begin
            if (SkewCycles == 0) begin
              // If no skew is tolerated, immediate signal integrity error
              state_d  = SigInt;
              sigint_o = 1'b1;
            end else begin
              // Mismatch with an edge: likely start of a tolerated skew
              state_d    = IsSkewing;
              skew_cnt_d = 1;
            end
          end
        end
        // diff pair must be correctly encoded, otherwise we got a sigint
        IsSkewing: begin
          if (diff_check_ok) begin
            state_d    = IsStd;
            level_d    = level;
            // Reset the skew counter
            skew_cnt_d = '0;
            // Assert event that was delayed due to skew resolution
            if (level) rise_o = 1'b1;
            else       fall_o = 1'b1;
          end else begin
            if (skew_cnt_q < SkewCycles) begin
              // Still within tolerated skew cycles
              skew_cnt_d = skew_cnt_q + 1;
            end else begin
              // Maximum skew cycles exceeded, raise an integrity issue
              state_d    = SigInt;
              sigint_o   = 1'b1;
              skew_cnt_d = '0;
            end
          end
        end
        // Signal integrity issue detected, remain here until resolved
        SigInt: begin
          sigint_o = 1'b1;
          if (diff_check_ok) begin
            state_d  = IsStd;
            sigint_o = 1'b0;
            level_d  = level;
            // Assert any event that was pending while in SigInt
            if (level) rise_o = 1'b1;
            else       fall_o = 1'b1;
          end
        end
        default : ;
      endcase
    end

    always_ff @(posedge clk_i or negedge rst_ni) begin : p_sync_reg
      if (!rst_ni) begin
        state_q    <= IsStd;
        diff_pq    <= 1'b0;
        diff_nq    <= 1'b1;
        level_q    <= 1'b0;
        skew_cnt_q <= '0;
      end else begin
        state_q    <= state_d;
        diff_pq    <= diff_pd;
        diff_nq    <= diff_nd;
        level_q    <= level_d;
        skew_cnt_q <= skew_cnt_d;
      end
    end

  //////////////////////////////////////////////////////////
  // fully synchronous case, no skew present in this case //
  //////////////////////////////////////////////////////////
  end else begin : gen_no_async
    logic diff_pq, diff_pd;

    // one reg for edge detection
    assign diff_pd = diff_pi;

    // Raise a signal integrity error when the differential signals have equal values.  This is
    // implemented with a `prim_xnor2` instead of behavioral code to prevent the synthesis tool from
    // optimizing away combinational logic on the complementary differential signals.
    prim_xnor2 #(
      .Width (1)
    ) u_xnor2_sigint (
      .in0_i (diff_pi),
      .in1_i (diff_ni),
      .out_o (sigint_o)
    );

    assign level_o = (sigint_o) ? level_q : diff_pi;
    assign level_d = level_o;

    // detect level transitions
    assign rise_o  = (~diff_pq &  diff_pi) & ~sigint_o;
    assign fall_o  = ( diff_pq & ~diff_pi) & ~sigint_o;
    assign event_o = rise_o | fall_o;

    always_ff @(posedge clk_i or negedge rst_ni) begin : p_edge_reg
      if (!rst_ni) begin
        diff_pq  <= 1'b0;
        level_q  <= 1'b0;
      end else begin
        diff_pq  <= diff_pd;
        level_q  <= level_d;
      end
    end
  end

  ////////////////
  // assertions //
  ////////////////

  // shared assertions
  // sigint -> level stays the same during sigint
  // $isunknown is needed to avoid false assertion in first clock cycle
    SigintLevelCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (##1 sigint_o |-> $stable(level_o)))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "SigintLevelCheck_A");                                                       
                                                              
    end
  // sigint -> no additional events asserted at output
    SigintEventCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (sigint_o |-> !event_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "SigintEventCheck_A");                                                       
                                                              
    end
    SigintRiseCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (sigint_o |-> !rise_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "SigintRiseCheck_A");                                                       
                                                              
    end
    SigintFallCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (sigint_o |-> !fall_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "SigintFallCheck_A");                                                       
                                                              
    end

  if (AsyncOn) begin : gen_async_assert
    // assertions for asynchronous case
// Correctly detect signal integrity issue:
    // If diff_pd and diff_nd are equal for (SkewCycles + 1) consecutive cycles, sigint_o must be
    // asserted.
      SigintCheck0_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (gen_async.diff_pd == gen_async.diff_nd [* (SkewCycles + 1)] |-> sigint_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "SigintCheck0_A");                                                       
                                                              
    end

    // The following assertions (SigintCheck1_A to SigintCheck4_A) describe specific
    // 1-cycle skew patterns that should lead to an edge. These are highly
    // specific to SkewCycles = 1. Therefore, they are only included when SkewCycles is 1.
    // the synchronizer adds 2 cycles of latency with respect to input signals.
    if (SkewCycles == 1) begin : gen_specific_skew_asserts
        SigintCheck1_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (##1 (gen_async.diff_pd ^ gen_async.diff_nd) &&
          $stable(gen_async.diff_pd) && $stable(gen_async.diff_nd) ##1
          $rose(gen_async.diff_pd) && $stable(gen_async.diff_nd) ##1
          $stable(gen_async.diff_pd) && $fell(gen_async.diff_nd)
          |-> rise_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "SigintCheck1_A");                                                       
                                                              
    end
        SigintCheck2_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (##1 (gen_async.diff_pd ^ gen_async.diff_nd) &&
          $stable(gen_async.diff_pd) && $stable(gen_async.diff_nd) ##1
          $fell(gen_async.diff_pd) && $stable(gen_async.diff_nd) ##1
          $stable(gen_async.diff_pd) && $rose(gen_async.diff_nd)
          |-> fall_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "SigintCheck2_A");                                                       
                                                              
    end
        SigintCheck3_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (##1 (gen_async.diff_pd ^ gen_async.diff_nd) &&
          $stable(gen_async.diff_pd) && $stable(gen_async.diff_nd) ##1
          $rose(gen_async.diff_nd) && $stable(gen_async.diff_pd) ##1
          $stable(gen_async.diff_nd) && $fell(gen_async.diff_pd)
          |-> fall_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "SigintCheck3_A");                                                       
                                                              
    end
        SigintCheck4_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (##1 (gen_async.diff_pd ^ gen_async.diff_nd) &&
          $stable(gen_async.diff_pd) && $stable(gen_async.diff_nd) ##1
          $fell(gen_async.diff_nd) && $stable(gen_async.diff_pd) ##1
          $stable(gen_async.diff_nd) && $rose(gen_async.diff_pd)
          |-> rise_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "SigintCheck4_A");                                                       
                                                              
    end
    end
    
    // Correctly detect edges: an event should be asserted within SkewCycles cycles after a valid
    // transition
      RiseCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni || sigint_o) !== '0) (!sigint_o ##1 $rose(gen_async.diff_pd) && (gen_async.diff_pd ^ gen_async.diff_nd) |->
        ##[0:SkewCycles] rise_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "RiseCheck_A");                                                       
                                                              
    end
      FallCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni || sigint_o) !== '0) (!sigint_o ##1 $fell(gen_async.diff_pd) && (gen_async.diff_pd ^ gen_async.diff_nd) |->
        ##[0:SkewCycles] fall_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "FallCheck_A");                                                       
                                                              
    end
      EventCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni || sigint_o) !== '0) (!sigint_o ##1 $changed(gen_async.diff_pd) && (gen_async.diff_pd ^ gen_async.diff_nd) |->
        ##[0:SkewCycles] event_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "EventCheck_A");                                                       
                                                              
    end
    // Correctly detect level: the output level should match diff_pd once the differential pair is
    // stable
      LevelCheck0_A: assert property (@(posedge clk_i) disable iff ((!rst_ni || sigint_o) !== '0) (// Stable for SkewCycles + 1 cycles
        !sigint_o && (gen_async.diff_pd ^ gen_async.diff_nd) [* (SkewCycles + 1)] |->
        gen_async.diff_pd == level_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "LevelCheck0_A");                                                       
                                                              
    end

  end else begin : gen_sync_assert
    // assertions for synchronous case

  // correctly detect sigint issue
      SigintCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (diff_pi == diff_ni |-> sigint_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "SigintCheck_A");                                                       
                                                              
    end
  

    // correctly detect edges
      RiseCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (##1 $rose(diff_pi)    && (diff_pi ^ diff_ni) |->  rise_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "RiseCheck_A");                                                       
                                                              
    end
      FallCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (##1 $fell(diff_pi)    && (diff_pi ^ diff_ni) |->  fall_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "FallCheck_A");                                                       
                                                              
    end
      EventCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (##1 $changed(diff_pi) && (diff_pi ^ diff_ni) |-> event_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "EventCheck_A");                                                       
                                                              
    end
    // correctly detect level
      LevelCheck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) ((diff_pi ^ diff_ni) |-> diff_pi == level_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_diff_decode_0/rtl/prim_diff_decode.sv", 5,         
         "LevelCheck_A");                                                       
                                                              
    end
  end

endmodule : prim_diff_decode
