// to make the code more concise.

// Register with asynchronous reset.


///////////////////////////
// Macro for Sparse FSMs //
///////////////////////////

// Simulation tools typically infer FSMs and report coverage for these separately. However, tools
// like Xcelium and VCS seem to have problems inferring FSMs if the state register is not coded in
// a behavioral always_ff block in the same hierarchy. To that end, this uses a modified variant
// with a second behavioral register definition for RTL simulations so that FSMs can be inferred.
// Note that in this variant, the __q output is disconnected from prim_sparse_fsm_flop and attached
// to the behavioral flop. An assertion is added to ensure equivalence between the
// prim_sparse_fsm_flop output and the behavioral flop output in that case.


 // PRIM_FLOP_MACROS_SV


 // PRIM_ASSERT_SV


module prim_alert_sender
  import prim_alert_pkg::*;
#(
  // enables additional synchronization logic
  parameter bit AsyncOn = 1'b1,
  // Number of cycles a differential skew is tolerated on the differential ack/ping signal.
  parameter int unsigned SkewCycles = 1,
  // alert sender will latch the incoming alert event permanently and
  // keep on sending alert events until the next reset.
  parameter bit IsFatal = 1'b0
) (
  input             clk_i,
  input             rst_ni,
  // alert test trigger (this will never be latched, even if IsFatal == 1)
  input             alert_test_i,
  // native alert from the peripheral
  input             alert_req_i,
  output logic      alert_ack_o,
  // state of the alert latching register
  output logic      alert_state_o,
  // ping input diff pair and ack diff pair
  input alert_rx_t  alert_rx_i,
  // alert output diff pair
  output alert_tx_t alert_tx_o
);


  /////////////////////////////////
  // decode differential signals //
  /////////////////////////////////
  logic ping_sigint, ping_event, ping_n, ping_p;

  // This prevents further tool optimizations of the differential signal.
  prim_sec_anchor_buf #(
    .Width(2)
  ) u_prim_buf_ping (
    .in_i({alert_rx_i.ping_n,
           alert_rx_i.ping_p}),
    .out_o({ping_n,
            ping_p})
  );

  prim_diff_decode #(
    .AsyncOn(AsyncOn),
    .SkewCycles(SkewCycles)
  ) u_decode_ping (
    .clk_i,
    .rst_ni,
    .diff_pi  ( ping_p      ),
    .diff_ni  ( ping_n      ),
    .level_o  (             ),
    .rise_o   (             ),
    .fall_o   (             ),
    .event_o  ( ping_event  ),
    .sigint_o ( ping_sigint )
  );

  logic ack_sigint, ack_level, ack_n, ack_p;

  // This prevents further tool optimizations of the differential signal.
  prim_sec_anchor_buf #(
    .Width(2)
  ) u_prim_buf_ack (
    .in_i({alert_rx_i.ack_n,
           alert_rx_i.ack_p}),
    .out_o({ack_n,
            ack_p})
  );

  prim_diff_decode #(
    .AsyncOn(AsyncOn),
    .SkewCycles(SkewCycles)
  ) u_decode_ack (
    .clk_i,
    .rst_ni,
    .diff_pi  ( ack_p      ),
    .diff_ni  ( ack_n      ),
    .level_o  ( ack_level  ),
    .rise_o   (            ),
    .fall_o   (            ),
    .event_o  (            ),
    .sigint_o ( ack_sigint )
  );


  ///////////////////////////////////////////////////
  // main protocol FSM that drives the diff output //
  ///////////////////////////////////////////////////
  typedef enum logic [2:0] {
    Idle,
    AlertHsPhase1,
    AlertHsPhase2,
    PingHsPhase1,
    PingHsPhase2,
    Pause0,
    Pause1
    } state_e;
  state_e state_d, state_q;
  logic alert_pq, alert_nq, alert_pd, alert_nd;
  logic sigint_detected;

  assign sigint_detected = ack_sigint | ping_sigint;


  // diff pair output
  assign alert_tx_o.alert_p = alert_pq;
  assign alert_tx_o.alert_n = alert_nq;

  // alert and ping set regs
  logic alert_set_d, alert_set_q, alert_clr;
  logic alert_test_set_d, alert_test_set_q;
  logic ping_set_d, ping_set_q, ping_clr;
  logic alert_req_trigger, alert_test_trigger, ping_trigger;

  // if handshake is ongoing, capture additional alert requests.
  logic alert_req;
  prim_sec_anchor_buf #(
    .Width(1)
  ) u_prim_buf_in_req (
    .in_i(alert_req_i),
    .out_o(alert_req)
  );

  assign alert_req_trigger = alert_req | alert_set_q;
  if (IsFatal) begin : gen_fatal
    assign alert_set_d = alert_req_trigger;
  end else begin : gen_recov
    assign alert_set_d = (alert_clr) ? 1'b0 : alert_req_trigger;
  end

  // the alert test request is always cleared.
  assign alert_test_trigger = alert_test_i | alert_test_set_q;
  assign alert_test_set_d = (alert_clr) ? 1'b0 : alert_test_trigger;

  logic alert_trigger;
  assign alert_trigger = alert_req_trigger | alert_test_trigger;

  assign ping_trigger = ping_set_q | ping_event;
  assign ping_set_d  = (ping_clr) ? 1'b0 : ping_trigger;


  // alert event acknowledge and state (not affected by alert_test_i)
  assign alert_ack_o = alert_clr & alert_set_q;
  assign alert_state_o = alert_set_q;

  // this FSM performs a full four phase handshake upon a ping or alert trigger.
  // note that the latency of the alert_p/n diff pair is at least one cycle
  // until it enters the receiver FSM. the same holds for the ack_* diff pair
  // input. in case a signal integrity issue is detected, the FSM bails out,
  // sets the alert_p/n diff pair to the same value and toggles it in order to
  // signal that condition over to the receiver.
  always_comb begin : p_fsm
    // default
    state_d   = state_q;
    alert_pd  = 1'b0;
    alert_nd  = 1'b1;
    ping_clr  = 1'b0;
    alert_clr = 1'b0;

    unique case (state_q)
      Idle: begin
        // alert always takes precedence
        if (alert_trigger || ping_trigger) begin
          state_d = (alert_trigger) ? AlertHsPhase1 : PingHsPhase1;
          alert_pd = 1'b1;
          alert_nd = 1'b0;
        end
      end
      // waiting for ack from receiver
      AlertHsPhase1: begin
        if (ack_level) begin
          state_d  = AlertHsPhase2;
        end else begin
          alert_pd = 1'b1;
          alert_nd = 1'b0;
        end
      end
      // wait for deassertion of ack
      AlertHsPhase2: begin
        if (!ack_level) begin
          state_d = Pause0;
          alert_clr = 1'b1;
        end
      end
      // waiting for ack from receiver
      PingHsPhase1: begin
        if (ack_level) begin
          state_d  = PingHsPhase2;
        end else begin
          alert_pd = 1'b1;
          alert_nd = 1'b0;
        end
      end
      // wait for deassertion of ack
      PingHsPhase2: begin
        if (!ack_level) begin
          ping_clr = 1'b1;
          state_d = Pause0;
        end
      end
      // pause cycles between back-to-back handshakes
      Pause0: begin
        state_d = Pause1;
      end
      // clear and ack alert request if it was set
      Pause1: begin
        state_d = Idle;
      end
      // catch parasitic states
      default : state_d = Idle;
    endcase

    // we have a signal integrity issue at one of the incoming diff pairs. this condition is
    // signalled by setting the output diffpair to zero. If the sigint has disappeared, we clear
    // the ping request state of this sender and go back to idle.
    if (sigint_detected) begin
      state_d   = Idle;
      alert_pd  = 1'b0;
      alert_nd  = 1'b0;
      ping_clr  = 1'b1;
      alert_clr = 1'b0;
    end
  end

  // This prevents further tool optimizations of the differential signal.
  prim_sec_anchor_flop #(
    .Width     (2),
    .ResetValue(2'b10)
  ) u_prim_flop_alert (
    .clk_i,
    .rst_ni,
    .d_i({alert_nd, alert_pd}),
    .q_o({alert_nq, alert_pq})
  );

  always_ff @(posedge clk_i or negedge rst_ni) begin : p_reg
    if (!rst_ni) begin
      state_q          <= Idle;
      alert_set_q      <= 1'b0;
      alert_test_set_q <= 1'b0;
      ping_set_q       <= 1'b0;
    end else begin
      state_q          <= state_d;
      alert_set_q      <= alert_set_d;
      alert_test_set_q <= alert_test_set_d;
      ping_set_q       <= ping_set_d;
    end
  end


  ////////////////
  // assertions //
  ////////////////

// however, since we use sequence constructs below, we need to wrap the entire block again.
// typically, the ASSERT macros already contain this INC_ASSERT macro.
// check whether all outputs have a good known state after reset
    AlertPKnownO_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (!$isunknown(alert_tx_o)))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "AlertPKnownO_A");                                                       
                                                              
    end                                           


  if (AsyncOn) begin : gen_async_assert
    sequence PingSigInt_S;
      alert_rx_i.ping_p == alert_rx_i.ping_n [*2];
    endsequence
    sequence AckSigInt_S;
      alert_rx_i.ping_p == alert_rx_i.ping_n [*2];
    endsequence

  // check propagation of sigint issues to output within three cycles, or four due to CDC
    // shift sequence to the right to avoid reset effects.
      SigIntPing_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (##1 PingSigInt_S |->
        ##[SkewCycles+2:SkewCycles+3] alert_tx_o.alert_p == alert_tx_o.alert_n))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "SigIntPing_A");                                                       
                                                              
    end
      SigIntAck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (##1 AckSigInt_S |->
        ##[SkewCycles+2:SkewCycles+3] alert_tx_o.alert_p == alert_tx_o.alert_n))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "SigIntAck_A");                                                       
                                                              
    end
  

    // Test in-band FSM reset request (via signal integrity error)
      InBandInitFsm_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (PingSigInt_S or AckSigInt_S |->
        ##[SkewCycles+2:SkewCycles+3] state_q == Idle))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "InBandInitFsm_A");                                                       
                                                              
    end
      InBandInitPing_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (PingSigInt_S or AckSigInt_S |->
        ##[SkewCycles+2:SkewCycles+3] !ping_set_q))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "InBandInitPing_A");                                                       
                                                              
    end
    // output must be driven diff unless sigint issue detected
      DiffEncoding_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) ((alert_rx_i.ack_p ^ alert_rx_i.ack_n) &&
        (alert_rx_i.ping_p ^ alert_rx_i.ping_n) |->
        ##[SkewCycles+2:SkewCycles+4] alert_tx_o.alert_p ^ alert_tx_o.alert_n))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "DiffEncoding_A");                                                       
                                                              
    end

    // handshakes can take indefinite time if blocked due to sigint on outgoing
    // lines (which is not visible here). thus, we only check whether the
    // handshake is correctly initiated and defer the full handshake checking to the testbench.
      PingHs_A: assert property (@(posedge clk_i) disable iff ((!rst_ni || (alert_tx_o.alert_p == alert_tx_o.alert_n)) !== '0) (##1 $changed(alert_rx_i.ping_p) &&
        (alert_rx_i.ping_p ^ alert_rx_i.ping_n) ##2 state_q == Idle |=>
        ##[0:1] $rose(alert_tx_o.alert_p)))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "PingHs_A");                                                       
                                                              
    end
  end else begin : gen_sync_assert
    sequence PingSigInt_S;
      alert_rx_i.ping_p == alert_rx_i.ping_n;
    endsequence
    sequence AckSigInt_S;
      alert_rx_i.ping_p == alert_rx_i.ping_n;
    endsequence

  // check propagation of sigint issues to output within one cycle
      SigIntPing_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (PingSigInt_S |=>
        alert_tx_o.alert_p == alert_tx_o.alert_n))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "SigIntPing_A");                                                       
                                                              
    end
      SigIntAck_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (AckSigInt_S |=>
        alert_tx_o.alert_p == alert_tx_o.alert_n))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "SigIntAck_A");                                                       
                                                              
    end
  

    // Test in-band FSM reset request (via signal integrity error)
      InBandInitFsm_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (PingSigInt_S or AckSigInt_S |=> state_q == Idle))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "InBandInitFsm_A");                                                       
                                                              
    end
      InBandInitPing_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (PingSigInt_S or AckSigInt_S |=> !ping_set_q))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "InBandInitPing_A");                                                       
                                                              
    end
    // output must be driven diff unless sigint issue detected
      DiffEncoding_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) ((alert_rx_i.ack_p ^ alert_rx_i.ack_n) &&
        (alert_rx_i.ping_p ^ alert_rx_i.ping_n) |=> alert_tx_o.alert_p ^ alert_tx_o.alert_n))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "DiffEncoding_A");                                                       
                                                              
    end
    // handshakes can take indefinite time if blocked due to sigint on outgoing
    // lines (which is not visible here). thus, we only check whether the handshake
    // is correctly initiated and defer the full handshake checking to the testbench.
      PingHs_A: assert property (@(posedge clk_i) disable iff ((!rst_ni || (alert_tx_o.alert_p == alert_tx_o.alert_n)) !== '0) (##1 $changed(alert_rx_i.ping_p) && state_q == Idle |=>
        $rose(alert_tx_o.alert_p)))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "PingHs_A");                                                       
                                                              
    end
  end

  // Test the alert state output.
    AlertState0_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (alert_set_q === alert_state_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "AlertState0_A");                                                       
                                                              
    end

  if (IsFatal) begin : gen_fatal_assert
      AlertState1_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (alert_req_i |=> alert_state_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "AlertState1_A");                                                       
                                                              
    end
      AlertState2_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (alert_state_o |=> $stable(alert_state_o)))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "AlertState2_A");                                                       
                                                              
    end
      AlertState3_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (alert_ack_o |=> alert_state_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "AlertState3_A");                                                       
                                                              
    end
  end else begin : gen_recov_assert
      AlertState1_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (alert_req_i && !alert_clr |=> alert_state_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "AlertState1_A");                                                       
                                                              
    end
      AlertState2_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (alert_req_i && alert_ack_o |=> !alert_state_o))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "AlertState2_A");                                                       
                                                              
    end
  end

  // The alert test input should not set the alert state register.
    AlertTest1_A: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (alert_test_i && !alert_req_i && !alert_state_o |=> $stable(alert_state_o)))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "AlertTest1_A");                                                       
                                                              
    end

  // if alert_req_i is true, handshakes should be continuously repeated
    AlertHs_A: assert property (@(posedge clk_i) disable iff ((!rst_ni || (alert_tx_o.alert_p == alert_tx_o.alert_n)) !== '0) (alert_req_i && state_q == Idle |=> $rose(alert_tx_o.alert_p)))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "AlertHs_A");                                                       
                                                              
    end

  // if alert_test_i is true, handshakes should be continuously repeated
    AlertTestHs_A: assert property (@(posedge clk_i) disable iff ((!rst_ni || (alert_tx_o.alert_p == alert_tx_o.alert_n)) !== '0) (alert_test_i && state_q == Idle |=> $rose(alert_tx_o.alert_p)))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_prim_alert_0/rtl/prim_alert_sender.sv", 5,         
         "AlertTestHs_A");                                                       
                                                              
    end



endmodule : prim_alert_sender
