  assign in = {
    ctrl_qe_i,
    ctrl_phase_i,
    ctrl_err_storage_i,
    op_i,
    mode_i,
    cipher_op_i,
    sideload_i,
    prng_reseed_rate_i,
    manual_operation_i,
    key_touch_forces_reseed_i,
    ctrl_gcm_qe_i,
    ctrl_gcm_phase_i,
    gcm_phase_i,
    start_i,
    key_iv_data_in_clear_i,
    data_out_clear_i,
    prng_reseed_i,
    mux_sel_err_i,
    sp_enc_err_i,
    lc_escalate_en_i,
    alert_fatal_i,
    key_sideload_valid_i,
    key_init_qe_i,
    iv_qe_i,
    data_in_qe_i,
    data_out_re_i,
    ctr_ready_i,
    ctr_we_i,
    cipher_in_ready_i,
    cipher_out_valid_i,
    cipher_crypt_i,
    cipher_dec_key_gen_i,
    cipher_prng_reseed_i,
    cipher_key_clear_i,
    cipher_data_out_clear_i,
    ghash_in_ready_i,
    ghash_out_valid_i,
    prng_reseed_ack_i,
    output_lost_i
  };

