  localparam int NumOutBufBits = $bits({
    ctrl_we_o,
    ctrl_gcm_we_o,
    gcm_init_done_o,
    alert_o,
    data_in_we_o,
    data_out_sel_o,
    data_out_we_o,
    data_in_prev_sel_o,
    data_in_prev_we_o,
    state_in_sel_o,
    add_state_in_sel_o,
    add_state_out_sel_o,
    ctr_inc32_o,
