  logic [NumOutBufBits-1:0] out, out_buf;

  assign out = {
    ctrl_we,
    ctrl_gcm_we,
    gcm_init_done,
    alert,
    data_in_we,
    data_out_sel,
    data_out_we,
    data_in_prev_sel,
    data_in_prev_we,
