          data_out_we_o,
          data_in_prev_sel_o,
          data_in_prev_we_o,
          state_in_sel_o,
          add_state_in_sel_o,
          add_state_out_sel_o,
          ctr_inc32_o,
          ctr_incr_o,
          cipher_in_valid_o,
          cipher_out_ready_o,
          cipher_crypt_o,
          cipher_dec_key_gen_o,
          cipher_prng_reseed_o,
          cipher_key_clear_o,
          cipher_data_out_clear_o,
          ghash_in_valid_o,
          ghash_out_ready_o,
          ghash_load_hash_subkey_o,
          key_init_sel_o,
          key_init_we_o,
          iv_sel_o,
          iv_we_o,
          prng_update_o,
          prng_reseed_req_o,
          start_we_o,
          key_iv_data_in_clear_we_o,
          data_out_clear_we_o,
          prng_reseed_o,
          prng_reseed_we_o,
          idle_o,
          idle_we_o,
          stall_o,
          stall_we_o,
          output_lost_o,
          output_lost_we_o,
          output_valid_o,
          output_valid_we_o,
          input_ready_o,
          input_ready_we_o} = out_buf;

endmodule
