    end                                           

    AlertTxKnown: assert property (@(posedge clk_i) disable iff ((!rst_ni) !== '0) (!$isunknown(alert_tx_o)))       
    else begin                                                                           
      $error("%0t: (%0s:%0d) [%m] [ASSERT FAILED] %0s", $time, "src/lowrisc_ip_aes_1.0/rtl/aes.sv", 5,         
         "AlertTxKnown");                                                       
                                                              
    end                                           


